# Preferences that used to live in the global Setting table and are now
# per-user (UserPref). default_thumb_percent stays in Setting -- it's read
# by the background scanner (services.py), which has no request/user.
_PER_USER_SETTING_KEYS = ("theme", "autoplay", "repeat", "shuffle", "loop")


def claim_existing_state(apps, schema_editor):
    """Assign all pre-auth (user=NULL) PlaybackState/WatchEvent rows, and the
    legacy per-user Setting values, to the first superuser found. If no
    superuser exists yet (createsuperuser hasn't been run), leave the rows
    NULL -- they're simply invisible to every user-scoped query until
    `python manage.py claim_state <username>` is run."""
    User = apps.get_model(settings.AUTH_USER_MODEL)
    PlaybackState = apps.get_model('library', 'PlaybackState')
    WatchEvent = apps.get_model('library', 'WatchEvent')
    Setting = apps.get_model('library', 'Setting')
    UserPref = apps.get_model('library', 'UserPref')

    owner = User.objects.filter(is_superuser=True).order_by('id').first()
    if not owner:
        logger.warning(
            "No superuser found -- existing playback/history rows left "
            "unclaimed. Run 'python manage.py createsuperuser' then "
            "'python manage.py claim_state <username>' to attach them.")
        return

    PlaybackState.objects.filter(user__isnull=True).update(user=owner)
    WatchEvent.objects.filter(user__isnull=True).update(user=owner)

    for row in Setting.objects.filter(key__in=_PER_USER_SETTING_KEYS):
        UserPref.objects.update_or_create(
            user=owner, key=row.key, defaults={'value': row.value})


